fn binary_search(v: &Vec<u64>, k: u64) -> usize {
    // We are given:
    // - v is sorted in non-decreasing order
    // - v is non-empty
    // - k appears at least once in v

    let mut left = 0usize;
    let mut right = v.len() - 1;

    // Invariant:
    //   left <= right < v.len()
    //   k appears within v[left..=right]
    // The interval shrinks each iteration ensuring termination.

    while left < right {
        let mid = left + (right - left) / 2;
        if v[mid] < k {
            // k must be in the right half excluding mid
            left = mid + 1;
        } else {
            // v[mid] >= k, so k is at mid or to the left
            right = mid;
        }
    }

    // Now left == right and points to an index where v[left] == k
    left
}